	SPI3->CR1 = SPI_CR1_SSI | SPI_CR1_SSM | SPI_CR1_MSTR; // Выбираем ведущий режим и программный NSS с внутренним высоким уровнем; остальные нулевые биты дают 8 бит, MSB первым, режим 0 и делитель 2.
