	I2C2->CCR = 80UL; // Выбираем стандартный режим и CCR = 80: при PCLK1 = 16 МГц частота SCL равна 16 000 000 / (2 × 80) = 100 кГц.
	I2C2->TRISE = 17UL; // Задаём TRISE = 16 + 1 для максимально допустимого времени нарастания 1000 нс в стандартном режиме при PCLK1 = 16 МГц.
	I2C2->CR1 |= I2C_CR1_PE; // Устанавливаем PE, включая настроенный периферийный блок I2C2.


